mapper.select:
select ii.id, ii.code, ii.name, ii.equipment_type_id, et.name as equipment_type_name, ii.result_type, ii.is_required as required, ii.enabled from inspection_item ii inner join equipment_type et on et.id = ii.equipment_type_id
and ( ii.code like concat('%', #{keyword}, '%') or ii.name like concat('%', #{keyword}, '%') )
and ii.equipment_type_id = #{equipmentTypeId}
and ii.result_type = #{resultType}
and ii.enabled = #{enabled}
order by ii.created_at desc, ii.id desc

mapper.update:
update inspection_item
set enabled = #{enabled}
where id = #{inspectionItemId}
